import { StyleFn } from "..";

export const ButtonGroup: StyleFn = (theme, mode) => {
  const { color, size } = theme;

  const focusAfter = {
    content: '""',
    position: "absolute",
    top: -2,
    left: 0,
    right: 0,
    bottom: -2,
    borderRadius: 0,
    border: "0 !important"
  };
  const focusFirst = {
    borderTopLeftRadius: 3,
    borderBottomLeftRadius: 3,
    left: -2,
  };
  const focusLast = {
    right: -2,
    borderTopRightRadius: 3,
    borderBottomRightRadius: 3,
  };
  const activeStyles = {
    color: color.text.neutral.minimal[mode],
    backgroundColor: color.surface.accent.default[mode],
    // hide dividers between prev/next buttons
    "&:before": { display: "none" },
    "& + button:before": { display: "none" },
  };

  return {
    root: {
      display: "inline-flex",
      boxSizing: "border-box",
      borderRadius: 3,
      border: `1px solid ${color.border.accent.interaction[mode]}`,
      "& button": {
        border: 0,
        borderRadius: 0,
        position: "relative",
        "&:before": {
          position: "absolute",
          zIndex: 1,
          content: "''",
          top: size.spacing[8],
          bottom: size.spacing[8],
          left: 0,
          borderLeft: `1px solid ${color.border.accent.interaction[mode]}`,
        },
        "&:focus": {
          border: "0 !important",
        },
        "&:focus-visible": {
          "&:after": focusAfter,
          boxShadow: `0 0 0 2px ${color.border.accent.focus[mode]} inset`,
          // hide divider on next button
          "& + button:before": { display: "none" },
        },
        "&:first-child": {
          "&:before": {
            display: "none",
          },
          borderTopLeftRadius: 2,
          borderBottomLeftRadius: 2,
          "&:focus-visible:after": focusFirst,
        },
        "&:last-child": {
          borderTopRightRadius: 2,
          borderBottomRightRadius: 2,
          "&:focus-visible:after": focusLast,
        },
        "&:active": activeStyles,
        "&[aria-pressed='true']": activeStyles,
      },
    },
  };
};
